-- Generated by make.sh from tests/test_support_phones.sql for the Supabase SQL editor. Expected: an error reading TESTRESULT ... fail=0.
-- Phone numbers (b30) and support tickets (b31), rolled back. Every row of the final select must say ok = true.
-- Writes only test users and their tickets; safe on staging (run in the SQL editor) and on a local copy.
begin;
create temp table r (n serial, name text, ok boolean, detail text);
grant all on r to authenticated, service_role;
grant usage, select on sequence r_n_seq to authenticated, service_role;

insert into auth.users (id, email, aud, role) values
  ('aaaaaaaa-0000-0000-0000-00000000f001', 'admin.st@eduwit.in', 'authenticated', 'authenticated'),
  ('aaaaaaaa-0000-0000-0000-00000000f002', 'priya.st@eduwit.in', 'authenticated', 'authenticated'),
  ('aaaaaaaa-0000-0000-0000-00000000f003', 'rohan.st@eduwit.in', 'authenticated', 'authenticated'),
  ('aaaaaaaa-0000-0000-0000-00000000f005', 'sneha.st@eduwit.in', 'authenticated', 'authenticated');
insert into b2c.users (user_id, email, full_name, role, is_active, is_test_user, phone) values
  ('aaaaaaaa-0000-0000-0000-00000000f001', 'admin.st@eduwit.in', 'ST Admin', 'admin', true, false, null),
  ('aaaaaaaa-0000-0000-0000-00000000f002', 'priya.st@eduwit.in', 'Priya ST', 'counsellor', true, true, '+919000000071'),
  ('aaaaaaaa-0000-0000-0000-00000000f003', 'rohan.st@eduwit.in', 'Rohan ST', 'sales_head', true, true, null),
  ('aaaaaaaa-0000-0000-0000-00000000f005', 'sneha.st@eduwit.in', 'Sneha ST', 'marketing', true, false, null);
create function pg_temp.as_user(p uuid) returns void language plpgsql as $f$
begin
  perform set_config('request.jwt.claims', json_build_object('sub', p, 'role', 'authenticated', 'session_id', ('bbbbbbbb-0000-0000-0000-' || right(p::text, 12))::uuid)::text, true);
end $f$;
create function pg_temp.as_system() returns void language plpgsql as $f$ begin perform set_config('request.jwt.claims', '', true); end $f$;
insert into b2c.session_checks (session_id, user_id, method)
select ('bbbbbbbb-0000-0000-0000-' || right(user_id::text, 12))::uuid, user_id, 'email_code' from b2c.users where email like '%.st@eduwit.in' on conflict do nothing;

-- ---------- phone numbers ----------
do $x$
declare e text; j jsonb;
begin
  perform pg_temp.as_user('aaaaaaaa-0000-0000-0000-00000000f002');
  begin perform b2c.phone_set('{"user_id": "aaaaaaaa-0000-0000-0000-00000000f002", "kind": "mobile", "number": "9000000072", "reason": "my new SIM"}'); e := 'set'; exception when others then e := sqlerrm; end;
  insert into r (name, ok, detail) values ('counsellor_cannot_change_numbers', e = 'not allowed', e);
  j := b2c.phone_mine();
  insert into r (name, ok, detail) values ('counsellor_sees_own_numbers', j ->> 'mobile' = '+919000000071', j::text);
  perform pg_temp.as_user('aaaaaaaa-0000-0000-0000-00000000f001');
  j := b2c.phone_set('{"user_id": "aaaaaaaa-0000-0000-0000-00000000f003", "kind": "mobile", "number": "90000 00073", "reason": "company SIM issued"}');
  insert into r (name, ok, detail) values ('admin_allocates_normalised', j ->> 'number' = '+919000000073'
    and (select phone from b2c.users where user_id = 'aaaaaaaa-0000-0000-0000-00000000f003') = '+919000000073', j::text);
  begin perform b2c.phone_set('{"user_id": "aaaaaaaa-0000-0000-0000-00000000f003", "kind": "mobile", "number": "+91 90000 00071", "reason": "swap"}'); e := 'set'; exception when others then e := sqlerrm; end;
  insert into r (name, ok, detail) values ('held_number_needs_move', e like 'this number is allocated to Priya ST%', e);
  j := b2c.phone_set('{"user_id": "aaaaaaaa-0000-0000-0000-00000000f003", "kind": "mobile", "number": "+91 90000 00071", "reason": "Priya leaves the team", "move": true}');
  insert into r (name, ok, detail) values ('number_moved', j ->> 'moved_from' = 'Priya ST'
    and (select phone from b2c.users where user_id = 'aaaaaaaa-0000-0000-0000-00000000f002') is null
    and (select phone from b2c.users where user_id = 'aaaaaaaa-0000-0000-0000-00000000f003') = '+919000000071'
    and exists (select 1 from b2c.notifications where user_id = 'aaaaaaaa-0000-0000-0000-00000000f002' and kind = 'phone_changed'), j::text);
  perform b2c.phone_set('{"user_id": "aaaaaaaa-0000-0000-0000-00000000f003", "kind": "caller_id", "number": "+91 11 4000 0001", "reason": "Exotel virtual number"}');
  begin perform b2c.phone_set('{"user_id": "aaaaaaaa-0000-0000-0000-00000000f003", "kind": "mobile", "number": "12", "reason": "typo"}'); e := 'set'; exception when others then e := sqlerrm; end;
  insert into r (name, ok, detail) values ('bad_number_refused', e like 'that does not look%', e);
  begin perform b2c.phone_set('{"user_id": "aaaaaaaa-0000-0000-0000-00000000f003", "kind": "mobile", "number": "9000000074"}'); e := 'set'; exception when others then e := sqlerrm; end;
  insert into r (name, ok, detail) values ('reason_required', e = 'give a reason', e);
  j := b2c.phone_directory();
  insert into r (name, ok, detail) values ('history_kept', (select count(*) from b2c.phone_history where user_id in ('aaaaaaaa-0000-0000-0000-00000000f002', 'aaaaaaaa-0000-0000-0000-00000000f003')) = 4
    and exists (select 1 from jsonb_array_elements(j -> 'history') h where h ->> 'reason' like 'moved to another person%' and h ->> 'old' = '+919000000071'),
    (select string_agg(kind || ':' || coalesce(old_number, '-') || '>' || coalesce(new_number, '-') || ' ' || coalesce(reason, ''), ' | ') from b2c.phone_history
      where user_id in ('aaaaaaaa-0000-0000-0000-00000000f002', 'aaaaaaaa-0000-0000-0000-00000000f003')));
  perform pg_temp.as_user('aaaaaaaa-0000-0000-0000-00000000f003');
  insert into r (name, ok, detail) values ('own_caller_id', b2c.phone_mine() ->> 'caller_id' = '+911140000001' and (b2c.phone_mine() ->> 'own_caller_id')::boolean, b2c.phone_mine()::text);
  perform pg_temp.as_system();
end $x$;

-- ---------- support tickets ----------
create temp table tk (k text primary key, id bigint);
grant all on tk to authenticated, service_role;
do $x$
declare j jsonb; e text; v bigint; m bigint;
begin
  insert into b2c.settings as s (key, value) values ('support', '{"developer_emails": [], "mailbox": null, "auto_close_days": 7}')
  on conflict (key) do update set value = excluded.value;
  perform pg_temp.as_user('aaaaaaaa-0000-0000-0000-00000000f002');
  begin perform b2c.support_create('{"kind": "bug", "subject": "x", "body": "The follow-ups page is blank"}'); e := 'made'; exception when others then e := sqlerrm; end;
  insert into r (name, ok, detail) values ('subject_required', e = 'write a subject', e);
  j := b2c.support_create('{"kind": "bug", "priority": "urgent", "subject": "Follow-ups page is blank", "body": "Since this morning the page shows nothing.",
                            "urls": ["https://crm.eduwit.in/s/followups", "javascript:alert(1)"], "page": "/s/followups"}');
  v := (j ->> 'ticket_id')::bigint; m := (j ->> 'message_id')::bigint;
  insert into tk values ('priya', v);
  insert into r (name, ok, detail) values ('ticket_created', j ->> 'number' = 'SUP-' || lpad(v::text, 4, '0')
    and (select urls from b2c.support_messages where id = m) = '{https://crm.eduwit.in/s/followups}'
    and exists (select 1 from b2c.notifications where kind = 'support' and user_id = 'aaaaaaaa-0000-0000-0000-00000000f001'), j::text);
  perform b2c.support_attach(m, jsonb_build_array(jsonb_build_object('path', 'tickets/' || v || '/0f0f0f0f-0000-4000-8000-000000000001.png', 'name', 'screen.png', 'type', 'image/png', 'size', 12345)));
  insert into r (name, ok, detail) values ('screenshot_attached', b2c.support_file_ok('tickets/' || v || '/0f0f0f0f-0000-4000-8000-000000000001.png'), null);
  begin perform b2c.support_attach(m, '[{"path": "tickets/999999/0f0f0f0f-0000-4000-8000-000000000001.png"}]'); e := 'attached'; exception when others then e := sqlerrm; end;
  insert into r (name, ok, detail) values ('attachment_path_checked', e = 'unknown file', e);
  -- Rohan cannot see Priya's ticket; Sneha raises her own (phone change)
  perform pg_temp.as_user('aaaaaaaa-0000-0000-0000-00000000f003');
  begin perform b2c.support_get(v); e := 'read'; exception when others then e := sqlerrm; end;
  insert into r (name, ok, detail) values ('others_cannot_see', e = 'not allowed' and not b2c.support_file_ok('tickets/' || v || '/0f0f0f0f-0000-4000-8000-000000000001.png')
    and jsonb_array_length(b2c.support_list('{"scope": "all"}') -> 'tickets') = 0, e);
  perform pg_temp.as_user('aaaaaaaa-0000-0000-0000-00000000f005');
  j := b2c.support_create('{"kind": "phone", "subject": "Please change my work number", "body": "New SIM: 90000 00079"}');
  insert into tk values ('sneha', (j ->> 'ticket_id')::bigint);
  -- the Admin sees every ticket
  perform pg_temp.as_user('aaaaaaaa-0000-0000-0000-00000000f001');
  j := b2c.support_list('{"scope": "all"}');
  insert into r (name, ok, detail) values ('admin_sees_all', (select count(*) from jsonb_array_elements(j -> 'tickets') t where (t ->> 'id')::bigint in (select id from tk)) = 2
    and (j -> 'counts' ->> 'open')::int >= 2, left((j -> 'counts')::text, 200));
  insert into r (name, ok, detail) values ('admin_mine_is_own', jsonb_array_length(b2c.support_list('{"scope": "mine"}') -> 'tickets') = 0, null);
  perform pg_temp.as_system();

  -- no developer address yet: nothing is taken, nothing is spent
  insert into r (name, ok, detail) values ('waits_for_developer_address', jsonb_array_length(b2c.support_mail_take(10)) = 0
    and (select mail_attempts from b2c.support_messages where id = m) = 0, null);
  insert into b2c.settings as s (key, value) values ('support', '{"developer_emails": ["dev@example.com"], "mailbox": "support@eduwit.in", "auto_close_days": 7}')
  on conflict (key) do update set value = excluded.value;
  j := b2c.support_mail_take(10);
  insert into r (name, ok, detail) values ('mail_taken_with_details', exists (select 1 from jsonb_array_elements(j) x where (x ->> 'message_id')::bigint = m and (x ->> 'first')::boolean
    and x ->> 'by' = 'Priya ST' and x ->> 'priority' = 'urgent' and jsonb_array_length(x -> 'attachments') = 1 and x -> 'developer_emails' ? 'dev@example.com'), left(j::text, 300));
  perform b2c.support_mail_done(m, null);
  insert into r (name, ok, detail) values ('mail_marked_sent', (select mailed_at is not null from b2c.support_messages where id = m)
    and not exists (select 1 from jsonb_array_elements(b2c.support_mail_take(10)) x where (x ->> 'message_id')::bigint = m), null);

  -- the developer answers by email: in progress, then fixed; a repeated email is ignored
  j := b2c.support_developer_reply(jsonb_build_object('ticket_id', v, 'body', 'Looking into it.', 'status', 'in_progress', 'from_email', 'dev@example.com', 'source', 'email', 'external_id', 'gm-1'));
  insert into r (name, ok, detail) values ('developer_reply_updates_ticket', (select status = 'in_progress' and developer_at is not null from b2c.support_tickets where id = v)
    and exists (select 1 from b2c.notifications where user_id = 'aaaaaaaa-0000-0000-0000-00000000f002' and kind = 'support' and link = '/s/support?t=' || v), j::text);
  j := b2c.support_developer_reply(jsonb_build_object('ticket_id', v, 'body', 'Looking into it.', 'status', 'in_progress', 'from_email', 'dev@example.com', 'source', 'email', 'external_id', 'gm-1'));
  insert into r (name, ok, detail) values ('repeated_email_ignored', (j ->> 'duplicate')::boolean and (select count(*) from b2c.support_messages where ticket_id = v and author_kind = 'developer') = 1, j::text);
  perform b2c.support_developer_reply(jsonb_build_object('ticket_id', v, 'body', 'Fixed in today''s release.', 'status', 'fixed', 'source', 'link'));
  perform pg_temp.as_user('aaaaaaaa-0000-0000-0000-00000000f002');
  j := b2c.support_get(v);
  insert into r (name, ok, detail) values ('thread_shows_answers', j ->> 'status' = 'fixed' and jsonb_array_length(j -> 'messages') = 3
    and (j -> 'messages' -> 2 ->> 'author_kind') = 'developer' and (j -> 'messages' -> 2 ->> 'status_to') = 'fixed', left(j::text, 300));
  -- the person replies: reopened and queued for the developer
  m := b2c.support_reply(v, 'Still blank on my phone.', array['https://crm.eduwit.in/s/followups']);
  insert into r (name, ok, detail) values ('reply_reopens', (select status from b2c.support_tickets where id = v) = 'open'
    and (select to_developer and mailed_at is null from b2c.support_messages where id = m), null);
  begin perform b2c.support_set_status(v, 'fixed'); e := 'set'; exception when others then e := sqlerrm; end;
  insert into r (name, ok, detail) values ('person_only_closes_or_reopens', e = 'you can close or reopen your ticket', e);
  perform b2c.support_set_status(v, 'closed', 'Works now, thanks.');
  insert into r (name, ok, detail) values ('person_closes', (select status = 'closed' and closed_by = 'person' from b2c.support_tickets where id = v)
    and (b2c.support_list('{"group": "closed"}') -> 'counts' ->> 'closed')::int = 1, null);
  perform pg_temp.as_system();

  -- a ticket marked fixed closes by itself after the set days
  perform b2c.support_developer_reply(jsonb_build_object('ticket_id', (select id from tk where k = 'sneha'), 'body', 'Done: your number is changed.', 'status', 'fixed', 'source', 'link'));
  update b2c.support_tickets set fixed_at = now() - interval '8 days' where id = (select id from tk where k = 'sneha');
  perform b2c.support_tick();
  insert into r (name, ok, detail) values ('fixed_auto_closes', (select status = 'closed' and closed_by = 'auto' from b2c.support_tickets where id = (select id from tk where k = 'sneha')), null);
  insert into r (name, ok, detail) values ('developer_side_service_only', not has_function_privilege('authenticated', 'b2c.support_developer_reply(jsonb)', 'execute')
    and not has_function_privilege('authenticated', 'b2c.support_mail_take(integer)', 'execute') and not has_function_privilege('authenticated', 'b2c.support_for_developer(bigint)', 'execute'), null);
end $x$;

insert into r (name, ok, detail)
select 'nothing_for_anon', not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'b2c' and has_function_privilege('anon', p.oid, 'execute')), null;

do $z$
declare f text;
begin
  select string_agg(n || ' ' || name || ': ' || coalesce(detail, ''), ' | ' order by n) into f from r where not ok;
  raise exception 'TESTRESULT pass=% fail=% %', (select count(*) from r where ok), (select count(*) from r where not ok), coalesce(f, '');
end $z$;
